                if (d.crisisResponse === 'emergency' && disruptionDays > 0) score += 10;
                else if (d.crisisResponse === 'ration') score += 8;
                if (ds.customerSatisfaction >= 60) score += 10;

                results.roundScore = score;

            } else if (period === 4) {
                var usdReduction4 = 0;
                var ebitdaChange = 0;

                if (d.acquisition === 'yes') {
                    ds.budgetRemaining -= 3200;
                    ebitdaChange += Math.round(12400 * 0.06);
                    if (ds.inkOption === 'D') {
                        usdReduction4 += 3;
                    } else {
                        usdReduction4 += 5;
                    }
                    ds.customerSatisfaction += 5;
                }

                if (d.usdLever === 'financial') {
                    usdReduction4 += 4;
                    ebitdaChange -= 180;
                } else if (d.usdLever === 'operational') {
                    usdReduction4 += 6;
                    ebitdaChange -= 350;
                } else {
                    usdReduction4 += 8;
                    ebitdaChange += 200;
                }

                ds.usdExposure = Math.max(30, Math.round((ds.usdExposure - usdReduction4) * 10) / 10);
                ds.ebitda += ebitdaChange;
                if (ds.ebitda < 500) ds.ebitda = 500;

                results.finalUsdExposure = ds.usdExposure;
                results.usdReduction = Math.round(usdReduction4 * 10) / 10;
                results.ebitdaChange = ebitdaChange;
                results.customerSatisfaction = ds.customerSatisfaction;
                results.targetAchieved = ds.usdExposure <= 50;
                results.usdExposure = ds.usdExposure;
                results.ebitda = ds.ebitda;

                var score = 0;
                if (ds.usdExposure <= 50) score += 25;
                else if (ds.usdExposure <= 55) score += 15;
                else score += 5;
                if (ds.customerSatisfaction >= 65) score += 10;
                if (d.acquisition === 'yes' && ds.inkOption !== 'D') score += 15;
                else if (d.acquisition === 'yes') score += 8;
                else score += 5;
                if (d.usdLever === 'commercial') score += 10;
                else if (d.usdLever === 'operational') score += 8;
                else score += 5;

                results.roundScore = score;
            }

            ds.usdExposureHistory.push(ds.usdExposure);
            ds.ebitdaHistory.push(ds.ebitda);
            ds.scoreHistory.push(results.roundScore || 0);

            // v1.1.0 FIX: persist a normalized 0-100 score into domainState so the
            // grading/reporting layer can read it. results_utils.php
            // (express_resolveDomainScore) reads domainState.performance.overallScore
            // (a normalized 0-100 grade) first, then top-level domainState.score.
            // The sim previously only tracked a per-round sum out of 110
            // (getPerformanceSummary.maxPossibleScore) and wrote no resolvable field,
            // so the instructor results panel showed an empty score.
            var _cum = ds.scoreHistory.reduce(function(s, v) { return s + (v || 0); }, 0);
            var _ov = Math.max(0, Math.min(100, Math.round(_cum / 110 * 100)));
            ds.performance = { overallScore: _ov, grade: (_ov >= 73 ? 'Expert' : _ov >= 55 ? 'Proficient' : _ov >= 36 ? 'Developing' : 'Beginner') };
            ds.score = _ov;
            results.overallScore = _ov;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._showRoundResults(state, results);
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return results;
        }

        _showRoundResults(state, results) {
            var panel = document.getElementById('roundResultsPanel');
            var text = document.getElementById('roundResultsText');
            if (!panel || !text) return;
            panel.style.display = 'block';

            var period = results.period;
            var html = '';

            if (period === 1) {
                html = '<strong>' + window.mySimulation.t('r1_result_title') + '</strong>';
                html += '<br>' + window.mySimulation.t('capital_freed') + ': ARS ' + results.capitalFreed + 'M';
                html += '<br>' + window.mySimulation.t('aluminum_cost_delta') + ': USD ' + results.aluminumCostDelta + 'K/year';
                html += '<br>' + window.mySimulation.t('tco_savings') + ': USD ' + results.tcoSavings + 'K/year';
                html += '<br>' + window.mySimulation.t('new_lead_time') + ': ' + results.newLeadTime + ' days';
            } else if (period === 2) {
                html = '<strong>' + window.mySimulation.t('r2_result_title') + '</strong>';
                html += '<br>' + window.mySimulation.t('usd_reduction') + ': ' + results.usdReduction + '%';
                html += '<br>' + window.mySimulation.t('new_usd_exposure') + ': ' + results.newUsdExposure + '%';
                html += '<br>' + window.mySimulation.t('budget_used') + ': ARS ' + results.budgetUsed + 'M';
                if (results.budgetExceeded) {
                    html += '<br><span style="color:#c0392b;font-weight:bold;">' + window.mySimulation.t('budget_exceeded_msg') + '</span>';
                }
            } else if (period === 3) {
                html = '<strong>' + window.mySimulation.t('r3_result_title') + '</strong>';
                html += '<br>' + window.mySimulation.t('disruption_days') + ': ' + results.disruptionDays;
                html += '<br>' + window.mySimulation.t('disruption_cost') + ': ARS ' + results.disruptionCost + 'M';
                html += '<br>' + window.mySimulation.t('deval_impact') + ': ARS ' + results.devalImpact + 'M';
                html += '<br>' + window.mySimulation.t('price_recovery') + ': ARS ' + results.priceRecovery + 'M';
                html += '<br>' + window.mySimulation.t('net_crisis_cost') + ': ARS ' + results.netCrisisCost + 'M';
            } else if (period === 4) {
                html = '<strong>' + window.mySimulation.t('r4_result_title') + '</strong>';
                html += '<br>' + window.mySimulation.t('final_usd') + ': ' + results.finalUsdExposure + '%';
                if (results.targetAchieved) {
                    html += '<br><span style="color:#27ae60;font-weight:bold;">' + window.mySimulation.t('target_achieved') + '</span>';
                } else {
                    html += '<br><span style="color:#e67e22;font-weight:bold;">' + window.mySimulation.t('target_not_achieved') + '</span>';
                }
            }

            text.innerHTML = html;
        }

