        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results && r.results.roundScore ? r.results.roundScore : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var lastState = history[history.length - 1];
            var finalExposure = lastState.results ? lastState.results.usdExposure || 72 : 72;
            var finalEbitda = lastState.results ? lastState.results.ebitda || 8230 : 8230;
            var targetAchieved = finalExposure <= 50;

            var performance = 'Beginner Supply Chain Manager';
            if (totalScore >= 80 && targetAchieved) performance = 'Expert Supply Chain Strategist';
            else if (totalScore >= 60) performance = 'Proficient Supply Chain Manager';
            else if (totalScore >= 40) performance = 'Developing Supply Chain Manager';

            var insights = [];
            if (targetAchieved) {
                insights.push('Successfully reduced USD exposure to target level — strong strategic alignment.');
            } else {
                insights.push('USD exposure target was not fully achieved — consider more aggressive operational changes.');
            }
            if (finalEbitda >= 7000) {
                insights.push('EBITDA preserved well through the transformation — good cost management.');
            } else {
                insights.push('EBITDA erosion was significant — balance transformation costs with profitability.');
            }

            return {
                totalScore: totalScore,
                maxPossibleScore: 110,
                finalUsdExposure: finalExposure,
                finalEbitda: finalEbitda,
                targetAchieved: targetAchieved,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (period === 1 && results.roundScore < 20) {
                return window.mySimulation.t('hint_r1_low');
            }
            if (period === 2 && results.budgetExceeded) {
                return window.mySimulation.t('hint_budget');
            }
            if (period === 3 && results.disruptionDays > 10) {
                return window.mySimulation.t('hint_disruption');
            }
            if (period === 4 && state.domainState.usdExposure > 55) {
                return window.mySimulation.t('hint_exposure_high');
            }
            return null;
        }

